<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/lifecycle/routes.php';
function pl_gate():void{cc_actor(false);if(crm_query("SELECT state FROM nd_schema_migrations WHERE version='026_owner_planning'")->fetchColumn()!=='applied')crm_fail(503,'Планирование ещё устанавливается.');}
function pl_calendar():array|false{return crm_query('SELECT * FROM nd_work_calendars WHERE id=1')->fetch();}
function pl_tasks():array{return crm_query("SELECT t.id,t.title,t.status,t.priority,t.due_at,t.version AS task_version,x.project_id,p.title AS project_label,p.status AS project_status,p.version AS project_version,p.order_id,o.number AS order_label,m.estimate_minutes,m.earliest_on,m.dependencies_json,m.planned_start,m.planned_end,COALESCE(m.version,0) AS version FROM nd_tasks t JOIN nd_task_projects x ON x.task_id=t.id JOIN nd_projects p ON p.id=x.project_id LEFT JOIN nd_orders o ON o.id=p.order_id LEFT JOIN nd_task_planning m ON m.task_id=t.id WHERE t.archived_at IS NULL AND p.archived_at IS NULL ORDER BY t.id")->fetchAll();}
function pl_hash(array $calendar,array $tasks):string{return hash('sha256',lc_json([$calendar,$tasks]));}
function pl_save_calendar(array $d):array{return crm_idempotent('planning/calendar',$d,function()use($d){$old=pl_calendar();if((int)($d['version']??-1)!==(int)($old['version']??0))crm_fail(409,'График изменился. Обновите страницу.');$m=$d['daily_minutes']??null;$days=$d['weekdays']??null;if(!is_int($m)||$m<1||$m>1440||!is_array($days)||!array_is_list($days)||!$days||count(array_unique($days))!==count($days))crm_fail(422,'Укажите реальные доступные минуты в день и рабочие дни.');foreach($days as $day)if(!is_int($day)||$day<1||$day>7)crm_fail(422,'Рабочие дни: понедельник–воскресенье.');if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите свой реальный рабочий график.');$exceptions=$d['exceptions']??[];if(!is_array($exceptions)||!array_is_list($exceptions))crm_fail(422,'Проверьте нерабочие даты.');foreach($exceptions as $date)if(!is_string($date)||!ct_iso_date($date))crm_fail(422,'Нерабочие даты указываются как ГГГГ-ММ-ДД.');$exceptions=array_values(array_unique($exceptions));sort($days);crm_query('INSERT INTO nd_work_calendars(id,daily_minutes,weekdays_json,exceptions_json) VALUES (1,?,?,?) ON DUPLICATE KEY UPDATE daily_minutes=VALUES(daily_minutes),weekdays_json=VALUES(weekdays_json),exceptions_json=VALUES(exceptions_json),version=version+1,reviewed_at=UTC_TIMESTAMP()',[$m,lc_json($days),lc_json($exceptions)]);return ['ok'=>true];});}
function pl_save_task(array $d):array{return crm_idempotent('planning/task',$d,function()use($d){$id=cc_id($d['task_id']??null);$t=crm_record('tasks',$id,true);crm_version(['version'=>$d['task_version']??null],$t);$rows=pl_tasks();$all=[];foreach($rows as $row)$all[(int)$row['id']]=$row;if(!isset($all[$id]))crm_fail(404,'Выберите действующую задачу проекта.');$row=$all[$id];if((int)($d['version']??-1)!==(int)$row['version'])crm_fail(409,'Оценка задачи изменилась.');$minutes=$d['estimate_minutes']??null;if($minutes!==null&&(!is_int($minutes)||$minutes<1||$minutes>5256000))crm_fail(422,'Укажите положительную оценку в минутах либо оставьте её неизвестной.');$earliest=$d['earliest_on']??null;if($earliest!==null&&!ct_iso_date($earliest))crm_fail(422,'Проверьте начальную дату.');$deps=$d['dependencies']??[];if(!is_array($deps)||!array_is_list($deps)||count($deps)!==count(array_unique($deps)))crm_fail(422,'Проверьте предшествующие задачи.');foreach($deps as $dep)if(!is_int($dep)||!isset($all[$dep])||$dep===$id||(int)$all[$dep]['project_id']!==(int)$row['project_id']||$all[$dep]['status']==='cancelled')crm_fail(422,'Предшественник должен быть другой действующей задачей этого проекта.');$all[$id]['dependencies_json']=lc_json($deps);pl_topological($all);crm_query('INSERT INTO nd_task_planning(task_id,estimate_minutes,earliest_on,dependencies_json) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE estimate_minutes=VALUES(estimate_minutes),earliest_on=VALUES(earliest_on),dependencies_json=VALUES(dependencies_json),planned_start=NULL,planned_end=NULL,version=version+1',[$id,$minutes,$earliest,lc_json($deps)]);return ['ok'=>true];});}
function pl_topological(array $all):array{$out=[];$visited=[];$active=[];$visit=function($id)use(&$visit,&$visited,&$active,&$out,$all){if(isset($visited[$id]))return;if(isset($active[$id]))crm_fail(422,'Зависимости образуют круг. Уберите обратную связь задач.');$active[$id]=true;foreach(json_decode($all[$id]['dependencies_json']??'[]',true) as $dep){if(!isset($all[$dep]))crm_fail(409,'Предшествующая задача больше недоступна. Перепроверьте зависимости.');$visit((int)$dep);}unset($active[$id]);$visited[$id]=true;$out[]=$id;};$ids=array_keys($all);$priority=['urgent'=>0,'high'=>1,'normal'=>2,'low'=>3];usort($ids,fn($a,$b)=>[$priority[$all[$a]['priority']],$all[$a]['due_at']??'9999',(int)$a]<=>[$priority[$all[$b]['priority']],$all[$b]['due_at']??'9999',(int)$b]);foreach($ids as $id)$visit($id);return $out;}
function pl_build(array $d):array{return crm_idempotent('planning/build',$d,function()use($d){$c=pl_calendar();if(!$c)crm_fail(409,'Сначала сохраните реальный рабочий график.');$tasks=pl_tasks();if(($d['source_hash']??'')!==pl_hash($c,$tasks))crm_fail(409,'Задачи, оценки или график изменились. Обновите страницу.');$start=cc_text($d,'start_on',10);if(!ct_iso_date($start))crm_fail(422,'Укажите начальную дату расчёта.');$days=json_decode($c['weekdays_json'],true);$exceptions=json_decode($c['exceptions_json'],true);$all=[];foreach($tasks as $t)$all[(int)$t['id']]=$t;$order=pl_topological($all);$date=new DateTimeImmutable($start);$used=[];$ends=[];$rows=[];$blocked=[];
 foreach($order as $id){$t=$all[$id];if(in_array($t['status'],['done','cancelled'],true)){if($t['status']==='done')$ends[$id]=$start;continue;}$reason=null;if($t['project_status']==='on_hold'||$t['status']==='blocked')$reason='Задача или проект приостановлены.';elseif(!$t['estimate_minutes'])$reason='Трудоёмкость ещё не проверена.';foreach(json_decode($t['dependencies_json']??'[]',true) as $dep)if(!isset($ends[$dep]))$reason='Предшествующая задача не запланирована или заблокирована.';if($reason){$blocked[]=['task_id'=>$id,'title'=>$t['title'],'reason'=>$reason];continue;}$at=new DateTimeImmutable(max($start,$t['earliest_on']??$start,...array_map(fn($id)=>$ends[$id]??$start,json_decode($t['dependencies_json']??'[]',true))));$remaining=(int)$t['estimate_minutes'];$first=null;$end=null;$guard=0;while($remaining>0){if(++$guard>36600)crm_fail(422,'План превышает допустимый горизонт100лет. Сократите оценку.');$day=$at->format('Y-m-d');$available=in_array((int)$at->format('N'),$days,true)&&!in_array($day,$exceptions,true)?max(0,(int)$c['daily_minutes']-($used[$day]??0)):0;if($available>0){$take=min($remaining,$available);$used[$day]=($used[$day]??0)+$take;$remaining-=$take;$first??=$day;$end=$day;}if($remaining>0)$at=$at->modify('+1 day');}$ends[$id]=$end;$due=$t['due_at']?(new DateTimeImmutable($t['due_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Europe/Kaliningrad'))->format('Y-m-d'):null;$rows[]=['task_id'=>$id,'title'=>$t['title'],'project_id'=>(int)$t['project_id'],'order_id'=>$t['order_id']?(int)$t['order_id']:null,'start_on'=>$first,'end_on'=>$end,'minutes'=>(int)$t['estimate_minutes'],'task_version'=>(int)$t['task_version'],'planning_version'=>(int)$t['version'],'project_version'=>(int)$t['project_version'],'due_on'=>$due,'deadline_conflict'=>$due!==null&&$end>$due];}
 $body=['calendar'=>$c,'start_on'=>$start,'rows'=>$rows,'blocked'=>$blocked,'daily_load'=>$used,'commercial_dates_changed'=>false,'task_execution_started'=>false];$raw=lc_json($body);crm_query('INSERT INTO nd_workload_plans(source_hash,body_json,checksum) VALUES (?,?,?)',[pl_hash($c,$tasks),$raw,hash('sha256',$raw)]);return ['ok'=>true,'plan_id'=>(int)db()->lastInsertId(),'plan'=>$body];});}
function pl_apply(array $d):array{return crm_idempotent('planning/apply',$d,function()use($d){$plan=crm_query('SELECT * FROM nd_workload_plans WHERE id=? FOR UPDATE',[cc_id($d['plan_id']??null)])->fetch();if(!$plan||!hash_equals($plan['checksum'],hash('sha256',$plan['body_json'])))crm_fail(404,'Расчёт не найден.');if($plan['applied_at'])return ['ok'=>true,'already_applied'=>true,'commercial_dates_changed'=>false];crm_query('SELECT id FROM nd_tasks ORDER BY id FOR UPDATE')->fetchAll();crm_query('SELECT id FROM nd_projects ORDER BY id FOR UPDATE')->fetchAll();crm_query('SELECT task_id FROM nd_task_planning ORDER BY task_id FOR UPDATE')->fetchAll();$c=crm_query('SELECT * FROM nd_work_calendars WHERE id=1 FOR UPDATE')->fetch();if(!$c||!hash_equals($plan['source_hash'],pl_hash($c,pl_tasks())))crm_fail(409,'Исходные данные изменились. Пересчитайте загрузку.');$body=json_decode($plan['body_json'],true);if($body['blocked'])crm_fail(409,'Устраните отсутствующие оценки и блокировки перед утверждением полного плана.');if(($d['confirm']??false)!==true||($d['checksum']??'')!==$plan['checksum'])crm_fail(422,'Проверьте и подтвердите точный расчёт.');foreach($body['rows'] as $row)crm_query('UPDATE nd_task_planning SET planned_start=?,planned_end=?,version=version+1 WHERE task_id=?',[$row['start_on'],$row['end_on'],$row['task_id']]);crm_query('UPDATE nd_workload_plans SET applied_at=UTC_TIMESTAMP() WHERE id=?',[$plan['id']]);lc_audit(['type'=>'owner','id'=>1],'planning',(int)$plan['id'],'workload_reviewed',null,['source_hash'=>$plan['source_hash'],'commercial_dates_changed'=>false,'task_execution_started'=>false]);return ['ok'=>true,'commercial_dates_changed'=>false];});}
function pl_plan(int $id):array{$p=crm_query('SELECT * FROM nd_workload_plans WHERE id=?',[$id])->fetch();if(!$p||!hash_equals($p['checksum'],hash('sha256',$p['body_json'])))crm_fail(404,'Расчёт не найден.');$p['body']=json_decode($p['body_json'],true);unset($p['body_json']);$tasks=[];foreach(pl_tasks() as $t)$tasks[(int)$t['id']]=$t;$c=pl_calendar();$stale=!$c||lc_json($c)!==lc_json($p['body']['calendar']);if(!$stale){if(!$p['applied_at'])$stale=!hash_equals($p['source_hash'],pl_hash($c,array_values($tasks)));else foreach($p['body']['rows'] as $r){$t=$tasks[$r['task_id']]??null;if(!$t||(int)$t['version']!==$r['planning_version']+1||(int)$t['task_version']!==$r['task_version']||(int)$t['project_version']!==$r['project_version']||(int)$t['estimate_minutes']!==$r['minutes']||$t['planned_start']!==$r['start_on']||$t['planned_end']!==$r['end_on'])$stale=true;}}$p['stale']=$stale;return $p;}
function pl_terms_source(int $id,int $order):array{$p=pl_plan($id);if(!$p['applied_at']||$p['stale'])crm_fail(409,'Расчёт загрузки не утверждён либо изменился. Перепроверьте план перед использованием в предложении.');$rows=array_values(array_filter($p['body']['rows'],fn($r)=>$r['order_id']===$order));if(!$rows)crm_fail(422,'Расчёт относится к другому заказу.');return ['plan_id'=>$id,'checksum'=>$p['checksum'],'rows'=>$rows,'contract_changed'=>false];}
